import { HARNESS_IDS, type HarnessId } from "../types/DashboardConstants";
import type { ModelPricing } from "./ModelPricing";
// Generated by `scripts/sync-model-pricing.mjs` from https://models.dev —
// see that script's header comment for why ctrlyoke prices every harness
// from this downloaded registry instead of a hand-typed table. Refresh via
// `npm run sync-model-pricing` / `npm run chores -- --task
// sync-model-pricing`; do not hand-edit.
import modelPricingRegistryData from "./generated/modelPricingRegistryData.json";

export interface RegistryCostEntry {
  input?: number;
  output?: number;
  cacheRead?: number;
  cacheWrite?: number;
}

export interface ModelPricingRegistryData {
  sourceUrl: string;
  generatedAt: string;
  providers: Record<string, Record<string, RegistryCostEntry>>;
}

const DATA = modelPricingRegistryData as ModelPricingRegistryData;

/**
 * Preferred provider buckets to try first for each harness, before falling
 * back to an exact-match sweep across the whole registry. This is a
 * disambiguation hint, not a restriction — every provider in the downloaded
 * table is still eligible as a last resort.
 */
const PREFERRED_PROVIDERS: Record<HarnessId, readonly string[]> = {
  [HARNESS_IDS.COPILOT_CLI]: ["github-copilot"],
  [HARNESS_IDS.CLAUDE_CLI]: ["anthropic"],
  [HARNESS_IDS.CODEX_CLI]: ["openai"],
  [HARNESS_IDS.OPENCODE_CLI]: ["opencode"],
  [HARNESS_IDS.QWEN_CLI]: ["alibaba"],
  [HARNESS_IDS.ANTIGRAVITY_CLI]: ["anthropic", "google", "groq"],
};

/**
 * Antigravity bakes its own reasoning-effort tier into the model ID suffix
 * (see `ANTIGRAVITY_CLI_MODELS` in ModelConstants.ts) — that suffix doesn't
 * exist in the upstream vendor's own model ID. Stripping it up front makes
 * the common case an exact match instead of relying on the fuzzy fallback.
 */
const ANTIGRAVITY_EFFORT_SUFFIXES = ["-high", "-medium", "-low", "-thinking"];

/**
 * Claude CLI's aliases (`CLAUDE_CLI_MODELS` in ModelConstants.ts) name a
 * *family*, not a specific dated model — Anthropic (and Claude CLI) moves
 * what "sonnet" points at over time. Rather than hand-pinning today's
 * version (which would just become another hand-maintained fact to chase),
 * `pickLatestVersionedModel` below picks whichever version of that family is
 * newest in the downloaded registry, every time pricing is resolved. This
 * map is vocabulary (which family a short alias means), not a price — it's
 * as stable as Anthropic's own naming scheme.
 */
const CLAUDE_ALIAS_FAMILY_PREFIX: Record<string, string> = {
  sonnet: "claude-sonnet-",
  opus: "claude-opus-",
  haiku: "claude-haiku-",
  fable: "claude-fable-",
};

/** Anthropic's own dated pinned snapshots (e.g. `-20250929`) are not what a
 * bare alias means ("latest"); exclude them from the version comparison. */
const DATED_SNAPSHOT_SUFFIX = /-\d{8}$/;

interface NormalizedLookup {
  /** The bare model ID to search for, with harness-specific decoration removed. */
  candidate: string;
  /** An explicit provider hint parsed out of the model ID itself, if any. */
  explicitProvider?: string;
}

/**
 * Reduce a ctrlyoke-internal model ID down to the bare vendor model ID
 * `models.dev` would use, plus an explicit provider hint when the harness's
 * own ID format encodes one (OpenCode's `<provider>/<model>` convention).
 */
function normalizeForHarness(
  harnessId: HarnessId,
  modelId: string
): NormalizedLookup {
  if (harnessId === HARNESS_IDS.OPENCODE_CLI) {
    const slashIndex = modelId.indexOf("/");
    if (slashIndex > 0) {
      return {
        candidate: modelId.slice(slashIndex + 1),
        explicitProvider: modelId.slice(0, slashIndex),
      };
    }
    return { candidate: modelId };
  }

  if (harnessId === HARNESS_IDS.ANTIGRAVITY_CLI) {
    for (const suffix of ANTIGRAVITY_EFFORT_SUFFIXES) {
      if (modelId.endsWith(suffix)) {
        return { candidate: modelId.slice(0, -suffix.length) };
      }
    }
    return { candidate: modelId };
  }

  if (harnessId === HARNESS_IDS.CLAUDE_CLI) {
    return { candidate: modelId.replace(/\[1m\]$/i, "") };
  }

  return { candidate: modelId };
}

/**
 * Split a version suffix like "-4-6" or "-5" into comparable numeric parts.
 */
function versionParts(key: string, familyPrefix: string): number[] {
  return key
    .slice(familyPrefix.length)
    .split("-")
    .map(Number)
    .filter((part) => !Number.isNaN(part));
}

/**
 * Among every un-dated key in `bucket` starting with `familyPrefix`, return
 * the entry for whichever has the highest version — e.g. picks
 * `claude-sonnet-5` over `claude-sonnet-4-6` over `claude-sonnet-4-5`.
 */
function pickLatestVersionedModel(
  bucket: Record<string, RegistryCostEntry>,
  familyPrefix: string
): RegistryCostEntry | undefined {
  const candidates = Object.keys(bucket).filter(
    (key) => key.startsWith(familyPrefix) && !DATED_SNAPSHOT_SUFFIX.test(key)
  );
  if (candidates.length === 0) return undefined;

  candidates.sort((a, b) => {
    const va = versionParts(a, familyPrefix);
    const vb = versionParts(b, familyPrefix);
    const len = Math.max(va.length, vb.length);
    for (let i = 0; i < len; i++) {
      const diff = (vb[i] ?? 0) - (va[i] ?? 0);
      if (diff !== 0) return diff;
    }
    return 0;
  });

  return bucket[candidates[0]];
}

/**
 * Look up a candidate model ID inside one provider's bucket. Exact and
 * `.../<candidate>` suffix matches are always tried (safe regardless of
 * bucket size — they can't cross-match an unrelated model). The looser
 * bidirectional substring match is only applied when `allowFuzzy` is set,
 * because running it across the *entire* multi-thousand-model registry
 * (rather than one harness-preferred bucket) risks matching an unrelated
 * model that merely shares a substring.
 */
function findInBucket(
  bucket: Record<string, RegistryCostEntry>,
  candidate: string,
  allowFuzzy: boolean
): RegistryCostEntry | undefined {
  if (bucket[candidate]) return bucket[candidate];

  const normalized = candidate.toLowerCase();
  const suffixKey = Object.keys(bucket).find((key) =>
    key.toLowerCase().endsWith(`/${normalized}`)
  );
  if (suffixKey) return bucket[suffixKey];

  if (!allowFuzzy) return undefined;

  const fuzzyKey = Object.keys(bucket).find((key) => {
    const lower = key.toLowerCase();
    return lower.includes(normalized) || normalized.includes(lower);
  });
  return fuzzyKey ? bucket[fuzzyKey] : undefined;
}

function toModelPricing(
  entry: RegistryCostEntry,
  providerId: string,
  data: ModelPricingRegistryData
): ModelPricing {
  return {
    inputPerMTok: entry.input ?? 0,
    outputPerMTok: entry.output ?? 0,
    ...(entry.cacheRead === undefined
      ? {}
      : { cachedInputPerMTok: entry.cacheRead }),
    ...(entry.cacheWrite === undefined
      ? {}
      : { cacheWritePerMTok: entry.cacheWrite }),
    sourceUrl: `${data.sourceUrl} (model-pricing registry, provider="${providerId}")`,
    verifiedOn: data.generatedAt,
  };
}

/**
 * Core matcher, parameterized over the registry data so tests can exercise
 * the normalization/lookup logic against a small fixture instead of the full
 * downloaded snapshot (which changes every time `sync-model-pricing.mjs` is
 * re-run). `getModelPricingFromRegistry` below is the real entry point,
 * bound to the actual downloaded data.
 */
export function resolveModelPricingFromRegistry(
  data: ModelPricingRegistryData,
  harnessId: HarnessId,
  modelId: string
): ModelPricing | undefined {
  if (!modelId) return undefined;

  const { candidate, explicitProvider } = normalizeForHarness(
    harnessId,
    modelId
  );
  const preferredProviders = PREFERRED_PROVIDERS[harnessId] ?? [];

  // Claude CLI's short aliases (sonnet/opus/haiku/fable[/[1m]]) name a
  // family, not a version — resolve to whichever version is newest in the
  // registry before falling through to generic matching (which would
  // otherwise just return the first substring hit in JSON key order, not
  // necessarily the latest one).
  if (harnessId === HARNESS_IDS.CLAUDE_CLI) {
    const familyPrefix = CLAUDE_ALIAS_FAMILY_PREFIX[candidate.toLowerCase()];
    const anthropicBucket = data.providers["anthropic"];
    if (familyPrefix && anthropicBucket) {
      const hit = pickLatestVersionedModel(anthropicBucket, familyPrefix);
      if (hit) return toModelPricing(hit, "anthropic", data);
    }
  }

  // 1. An explicit provider hint parsed from the model ID itself (OpenCode's
  //    `<provider>/<model>`) is trusted enough for the fuzzy substring match.
  if (explicitProvider) {
    const bucket = data.providers[explicitProvider];
    if (bucket) {
      const hit = findInBucket(bucket, candidate, true);
      if (hit) return toModelPricing(hit, explicitProvider, data);
    }
  }

  // 2. Harness-preferred provider buckets, also eligible for the fuzzy match.
  for (const providerId of preferredProviders) {
    if (providerId === explicitProvider) continue;
    const bucket = data.providers[providerId];
    if (!bucket) continue;
    const hit = findInBucket(bucket, candidate, true);
    if (hit) return toModelPricing(hit, providerId, data);
  }

  // 3. Last resort: an exact/suffix-only sweep across every remaining
  //    provider. No fuzzy substring matching here — across ~6,800 models
  //    from unrelated vendors, a loose substring match is as likely to be
  //    wrong as right.
  for (const [providerId, bucket] of Object.entries(data.providers)) {
    if (providerId === explicitProvider) continue;
    if (preferredProviders.includes(providerId)) continue;
    const hit = findInBucket(bucket, candidate, false);
    if (hit) return toModelPricing(hit, providerId, data);
  }

  return undefined;
}

/**
 * Resolve a best-effort list-price estimate for any harness's model from the
 * downloaded models.dev snapshot. This is the sole source of
 * `ModelPricing` data in ctrlyoke — see `getModelPricing` in
 * `ModelPricing.ts`, which calls this after checking for a user override.
 */
export function getModelPricingFromRegistry(
  harnessId: HarnessId,
  modelId: string
): ModelPricing | undefined {
  return resolveModelPricingFromRegistry(DATA, harnessId, modelId);
}
